import { expect, it, vi } from "vitest";
import { StudentSessionCsrf } from "../../src/http/student-session-csrf";
import { isCanonicalToken } from "../../src/infrastructure/student-session-cookie";

const origin = "https://nssscdl.test";
const raw = "A".repeat(43);
// Independent known SHA-256 vector, not generated by the implementation.
const expected = "p35EDD5VELmGsajOaMrGPH6WzW74IYQLZ9g-3qTG_74";
const request = (value = expected) => new Request(origin, { headers: {
  cookie: `__Host-student_session=${raw}`, origin, "x-csrf-token": value,
} });

it("[#865 canonical CSRF] uses domain-prefixed raw Session and padding-free SHA-256", async () => {
  expect(isCanonicalToken(expected)).toBe(true);
  expect(isCanonicalToken("A".repeat(42) + "B")).toBe(false);
  const digest = vi.spyOn(crypto.subtle, "digest");
  try {
    expect(await new StudentSessionCsrf(origin).validate(request())).toBe(true);
    expect(digest).toHaveBeenCalledExactlyOnceWith("SHA-256", new TextEncoder().encode("student-csrf-v1:" + raw));
  } finally { digest.mockRestore(); }
});

it("[#865 fixed-length compare] examines all characters for first, middle and final mismatches", async () => {
  for (const index of [0, 21, 42]) {
    const changed = expected.slice(0, index) + (index === 42 ? "E" : "A") + expected.slice(index + 1);
    expect(isCanonicalToken(changed)).toBe(true);
    const charCode = vi.spyOn(String.prototype, "charCodeAt");
    let result: boolean;
    let visited: number[];
    try {
      result = await new StudentSessionCsrf(origin).validate(request(changed));
      visited = charCode.mock.calls.slice(-86).map((args) => args[0]);
    } finally { charCode.mockRestore(); }
    expect(result).toBe(false);
    expect(visited).toEqual(Array.from({ length: 43 }, (_, position) => [position, position]).flat());
  }
});

it("[#865 config failure] rejects undefined origin before digest", async () => {
  const digest = vi.spyOn(crypto.subtle, "digest");
  try {
    await expect(new StudentSessionCsrf(undefined).validate(request())).rejects.toMatchObject({ code: "SERVICE_UNAVAILABLE" });
    expect(digest).not.toHaveBeenCalled();
  } finally { digest.mockRestore(); }
});
